"""Use certified straight terminal runs for physical Bundle cap construction.

Adaptive offset certification can leave hundreds of derived samples on an
otherwise straight terminal piece. The first such interval is an accidental
cap-depth limit. Coalesce only redundant terminal records, stopping before the
next authored control and within a bounded physical reach. Every skipped record
must lie on the same physical segment within the existing four-micrometre cap
coordinate budget. Source ranks must also agree to float32 parameter precision.
Curved runs keep their original records.
Source objects, authored controls and the acceptance checks are unchanged.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import bundle_axis_nodes as axis

NAME = 'Prochitecture Streets / Certified linear Bundle terminal records v1'
TOLERANCE = 4e-6
RANK_TOLERANCE = 2.**-23  # two float32 ulps for normalized ranks in [0, 1]
PREFIX_CANDIDATES = 8


def build(*, certified_prefixes=False):
    name = NAME+' / certified prefixes v2' if certified_prefixes else NAME
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree'); g = _Nodes(tree)
    for name, kind in (('Boundary', 'Geometry'), ('Axis', 'Vector'),
                       ('Extend Start', 'Bool'), ('Extend End', 'Bool'), ('Reach', 'Float')):
        item = tree.interface.new_socket(name=name, in_out='INPUT', socket_type='NodeSocket'+kind)
        if name == 'Reach': item.default_value = 1.
    tree.interface.new_socket(name='Boundary', in_out='OUTPUT', socket_type='NodeSocketGeometry')
    inp = g.node('NodeGroupInput', 'Original certified records and selected physical caps')
    out = g.node('NodeGroupOutput', 'Ordered terminal records retaining every authored control')
    source = inp.outputs['Boundary']; count = axis._size(g, source)
    last = g.math('SUBTRACT', count, 1.)
    index = g.node('GeometryNodeInputIndex', 'Original record identity').outputs[0]
    physical = g.named('st_axis_xy', 'FLOAT_VECTOR')
    rank = g.named('st_station_t', 'FLOAT')
    control_node = g.node('GeometryNodeInputNamedAttribute', 'Authored controls must be identifiable')
    control_node.data_type = 'BOOLEAN'; control_node.inputs['Name'].default_value = 'st_axis_control'
    control = control_node.outputs['Attribute']; ends = []
    for at_end, key in ((False, 'Extend Start'), (True, 'Extend End')):
        inward = g.math('SUBTRACT', last, index) if at_end else index
        address = lambda value: g.math('SUBTRACT', last, value) if at_end else value
        first = g.sample(source, physical, last if at_end else 0, 'FLOAT_VECTOR')
        first_rank = g.sample(source, rank, last if at_end else 0, 'FLOAT')
        next_control = g.stat(source, g.switch(g.all(control, g.compare(inward, 0., 'GREATER_THAN')), 1e9, inward))
        advance = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', physical, first), inp.outputs['Axis'])
        if at_end: advance = g.math('MULTIPLY', -1., advance)
        available = g.all(g.compare(inward, next_control, 'LESS_EQUAL'),
                          g.compare(advance, inp.outputs['Reach'], 'LESS_EQUAL'),
                          g.compare(advance, 1e-5, 'GREATER_THAN'))
        chosen = g.math('MAXIMUM', 1., g.stat(source, g.switch(available, 0., inward), output='Max'))
        def certify(candidate):
            end = g.sample(source, physical, address(candidate), 'FLOAT_VECTOR')
            end_rank = g.sample(source, rank, address(candidate), 'FLOAT')
            delta = g.vector('SUBTRACT', end, first)
            # Prove the footprint in local differences. Converting a rounded
            # rank back to a world coordinate near 100 m adds an axial float32
            # ulp. Physical collinearity and parameter agreement are distinct.
            local = g.vector('SUBTRACT', physical, first)
            fraction = g.math('DIVIDE', g.vector('DOT_PRODUCT', local, delta),
                              g.vector('DOT_PRODUCT', delta, delta))
            expected = g.vector('SCALE', delta, fraction)
            inside = g.compare(inward, candidate, 'LESS_EQUAL')
            error = g.switch(inside, 0., g.vector('DISTANCE', local, expected))
            expected_rank = g.math('ADD', first_rank, g.math('MULTIPLY', fraction,
                                   g.math('SUBTRACT', end_rank, first_rank)))
            rank_error = g.switch(inside, 0., g.math('ABSOLUTE', g.math('SUBTRACT', rank, expected_rank)))
            return g.all(inp.outputs[key], g.sample(source, control_node.outputs['Exists'], 0, 'BOOLEAN'),
                g.compare(candidate, next_control, 'LESS_EQUAL'),
                g.compare(g.math('ABSOLUTE', g.math('SUBTRACT', end_rank, first_rank)), 1e-8, 'GREATER_THAN'),
                g.compare(g.stat(source, error, output='Max'), TOLERANCE, 'LESS_EQUAL'),
                g.compare(g.stat(source, rank_error, output='Max'), RANK_TOLERANCE, 'LESS_EQUAL'))
        accepted = 1.
        # A failed long run does not imply every shorter prefix is invalid.
        # Try a finite set with the identical physical and parameter checks.
        # Order switches so the existing longest candidate always wins when
        # certified. Failed candidates never remove records.
        # The rank test is not monotonic in prefix length: rounded input ranks
        # can agree with one retained endpoint and disagree with its neighbour.
        # Sample eight lengths across the reach, rather than assuming that a
        # binary shortening search can find every usable prefix.
        fractions = tuple(k/PREFIX_CANDIDATES for k in range(1, PREFIX_CANDIDATES+1)) if certified_prefixes else (1.,)
        for fraction in fractions:
            candidate = chosen if fraction == 1. else g.math('MAXIMUM', 1., g.math('FLOOR', g.math('MULTIPLY', chosen, fraction)))
            accepted = g.switch(certify(candidate), accepted, candidate)
        ends.append(accepted)
    # Never let the two optional reductions erase the body between the caps.
    separate = g.compare(g.math('ADD', *ends), last, 'LESS_THAN')
    starts = [g.switch(separate, 1., value) for value in ends]
    keep = g.all(g.either(g.compare(index, 0.), g.compare(index, starts[0], 'GREATER_EQUAL')),
                 g.either(g.compare(index, last), g.compare(index, g.math('SUBTRACT', last, starts[1]), 'LESS_EQUAL')))
    retained = axis._select(g, source, keep, 'Only proven redundant terminal samples removed')
    line = g.node('GeometryNodeMeshLine', 'Reconnect retained records in original order')
    g.set(axis._size(g, retained), line.inputs['Count']); result = line.outputs['Mesh']
    for name, kind in (('st_axis_xy', 'FLOAT_VECTOR'), ('st_station_t', 'FLOAT'),
                       ('st_axis_control', 'BOOLEAN'), ('st_station_knot', 'BOOLEAN')):
        result = g.store(result, name, g.sample(retained, g.named(name, kind), index, kind), kind)
    active = g.either(*(g.compare(value, 1., 'GREATER_THAN') for value in starts))
    g.set(g.switch(active, source, result, 'GEOMETRY'), out.inputs['Boundary'])
    if certified_prefixes: tree['st_certified_terminal_prefixes'] = 2
    return tree


def evaluate(g, boundary, direction, enabled):
    call = g.node('GeometryNodeGroup', 'Certified physical terminal run, independent of sampling density')
    call.node_tree = build()
    for name, value in (('Boundary', boundary), ('Axis', direction),
                        ('Extend Start', enabled[0]), ('Extend End', enabled[1])):
        g.set(value, call.inputs[name])
    return call.outputs['Boundary']


def cap_depth(g, target_cell, independent):
    """Keep a new cap comparable to its prescribed transverse cell spacing.

The step pattern has two columns across one shoulder strip. A quarter-cell
depth gives each half an eighth-cell width, before the unchanged actual shape
checks. The existing half-metre maximum and certified source-run cut still cap
this heuristic. Legacy cap branches retain exactly their original depth.
"""
    candidate = g.math('MINIMUM', .5, g.math('MULTIPLY', .25, target_cell))
    return g.switch(independent, .5, candidate)


def install_saved(original):
    """Apply the canonical terminal-record preparation to an unpublished v9."""
    if original.get('st_bundle_independent_free_caps') != 1:
        raise ValueError('Expected the initial independent-cap experiment')
    tree = original.copy(); tree.name = original.name.replace(' v9 /', ' v10 /'); g = _Nodes(tree)
    body, = [n for n in tree.nodes if n.label == 'True common-fibre body behind unchanged free-end caps']
    incoming = lambda socket: next(link.from_socket for link in socket.links)
    direction = incoming(body.inputs['Axis'])
    selected = [incoming(body.inputs['Cut '+key]) for key in ('Start', 'End')]
    independent = incoming(selected[0].node.inputs['Switch'])
    assert incoming(selected[1].node.inputs['Switch']) == independent
    enabled = [g.all(independent, value) for value in selected]
    for k in range(4):
        old = incoming(body.inputs['Boundary '+str(k)])
        targets = [link.to_socket for link in old.links]
        result = evaluate(g, old, direction, enabled)
        for socket in targets: g.set(result, socket)
    inp = next(n for n in tree.nodes if n.type == 'GROUP_INPUT')
    depth = cap_depth(g, inp.outputs['Target Cell'], independent)
    g.set(depth, body.inputs['Maximum Depth'])
    for node in tree.nodes:
        if node.label in ('Profiled start cap', 'Profiled end cap'):
            g.set(depth, node.inputs['Maximum Depth'])
    tree['st_bundle_independent_free_caps'] = 2
    return tree
